package com.jotafy.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 LinearLayout root,content;int days=1;String csv="";final ExecutorService io=Executors.newSingleThreadExecutor();int generation=0;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(8),0,dp(8));return t;}
 void button(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);parent.addView(b);b.setOnClickListener(v->action.run());}
 @Override public void onCreate(Bundle s){super.onCreate(s);getWindow().setStatusBarColor(0xff241338);getWindow().setNavigationBarColor(0xff241338);home();}
 void home(){generation++;ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(20),dp(20),dp(28));root.setBackgroundColor(0xfff6f2fa);sc.addView(root);setContentView(sc);root.addView(text("JotaFy",34,0xff7024aa));root.addView(text("Suas vendas, sem complicação",16,0xff554b60));LinearLayout periods=new LinearLayout(this);root.addView(periods);for(int n:new int[]{1,7,30}){Button b=new Button(this);b.setText(n==1?"Hoje":n+" dias");periods.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{days=n;refresh();});}content=new LinearLayout(this);content.setOrientation(1);root.addView(content);button(root,"Atualizar vendas",()->refresh());button(root,"Exportar resumo CSV",()->{if(csv.isEmpty()){toast("Atualize as vendas primeiro.");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"JotaFy-"+days+"-dias.csv");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,8);});button(root,"Conexão e chave de acesso",()->settings());button(root,"Ativar notificações",()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);return;}startMonitor();});button(root,"Parar monitoramento",()->{stopService(new Intent(this,MonitorService.class));toast("Monitoramento parado.");});root.addView(text("Valores brutos • horário de Brasília\nNotificações consultadas a cada minuto enquanto o monitoramento estiver ativo. O Android pode limitar a execução em segundo plano (Android 15: até 6h por dia). Reabra o app para retomar.",12,0xff665d70));refresh();}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void startMonitor(){startForegroundService(new Intent(this,MonitorService.class));toast("Monitoramento iniciado. Veja o status nas notificações.");}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==7&&g.length>0&&g[0]==0)startMonitor();}
 void settings(){generation++;stopService(new Intent(this,MonitorService.class));LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(20),dp(12),dp(20),0);EditText url=new EditText(this);url.setSingleLine(true);url.setHint("https://jotafy.seu-subdominio.workers.dev");url.setText(Store.prefs(this).getString("url",""));box.addView(url);EditText token=new EditText(this);token.setHint("Chave de acesso JotaFy (64 caracteres)");token.setInputType(129);box.addView(token);new AlertDialog.Builder(this).setTitle("Conectar JotaFy").setMessage("Use a chave própria do monitor. Não use o token do Mercado Pago. Ao trocar conexão, ative novamente as notificações.").setView(box).setNegativeButton("Cancelar",(d,w)->refresh()).setPositiveButton("Salvar",(d,w)->{try{Store.save(this,url.getText().toString().trim(),token.getText().toString().trim());csv="";refresh();}catch(Exception e){toast(e.getMessage());}}).show();}
 void refresh(){final int request=++generation,period=days;csv="";content.removeAllViews();content.addView(text("Consultando…",16,0xff554b60));io.submit(()->{try{JSONObject j=Store.load(this,period,false);runOnUiThread(()->{if(request!=generation||isFinishing())return;try{render(j,period);}catch(Exception e){toast("Resposta inválida do servidor.");}});}catch(Exception e){runOnUiThread(()->{if(request!=generation||isFinishing())return;content.removeAllViews();content.addView(text(e.getMessage(),16,0xffa02255));});}});}
 void render(JSONObject j,int period)throws Exception{content.removeAllViews();JSONObject s=j.getJSONObject("summary");content.addView(text(period==1?"Vendas de hoje":"Últimos "+period+" dias",20,0xff241338));content.addView(text(Store.money(s.getLong("revenue")),38,0xff7024aa));content.addView(text(s.getInt("sales")+" vendas aprovadas • receita bruta",16,0xff554b60));content.addView(text("Formas de pagamento",21,0xff241338));StringBuilder report=new StringBuilder("Período (dias);Vendas aprovadas;Receita bruta BRL\n"+period+";"+s.getInt("sales")+";"+String.format(java.util.Locale.US,"%.2f",s.getLong("revenue")/100.0)+"\n\nForma;Vendas\n");JSONArray methods=j.getJSONArray("methods");if(methods.length()==0)content.addView(text("Nenhuma venda aprovada no período.",15,0xff665d70));for(int i=0;i<methods.length();i++){JSONObject m=methods.getJSONObject(i);String label=Store.label(m.getString("method"));content.addView(text(label+"   •   "+m.getInt("sales"),17,0xff241338));report.append(label+";"+m.getInt("sales")+"\n");}csv=report.toString();content.addView(text("Últimos eventos",21,0xff241338));JSONArray events=j.getJSONArray("recent");if(events.length()==0)content.addView(text("Nenhum evento registrado. Vendas antigas podem não ter detalhes de pagamento.",14,0xff665d70));java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("dd/MM HH:mm",new java.util.Locale("pt","BR"));f.setTimeZone(java.util.TimeZone.getTimeZone("America/Sao_Paulo"));for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);content.addView(text(Store.label(e.getString("kind"))+" • "+Store.money(e.getLong("amount_cents"))+"\n"+Store.label(e.getString("method"))+" • "+f.format(new java.util.Date(e.getLong("created_at"))),15,0xff554b60));}content.addView(text("Atualizado agora. Totais excluem vendas reembolsadas ou contestadas. Relatório CSV contém o resumo do período.",12,0xff665d70));}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==8&&result==RESULT_OK&&data!=null){try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(("\uFEFF"+csv).getBytes("UTF-8"));toast("Relatório salvo.");}catch(Exception e){toast("Não foi possível salvar o relatório.");}}}
 @Override public void onDestroy(){generation++;io.shutdownNow();super.onDestroy();}
}
